function lengthOfLIS(nums: number[]): number {
  // tails[k] — наименьший возможный последний элемент
  // среди всех возрастающих подпоследовательностей длины k + 1.
  // Массив tails всегда строго возрастает.
  const tails: number[] = [];

  for (const x of nums) {
    // Бинарный поиск: первая позиция, где tails[pos] >= x
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1;
      else hi = mid;
    }

    if (lo === tails.length) {
      // x больше всех хвостов — удлиняем самую длинную подпоследовательность
      tails.push(x);
    } else {
      // Заменяем хвост: подпоследовательность длины lo + 1 теперь
      // заканчивается меньшим числом, и её легче продолжить
      tails[lo] = x;
    }
  }

  // Число хвостов — длина самой длинной возрастающей подпоследовательности
  return tails.length;
}

// Время: O(n log n) — бинарный поиск для каждого элемента
// Память: O(n) — массив tails
